-- Generated by scripts/build-ai-model-feedback-catalog.ts.
-- Apply core first, deploy ask-bob AND bob-worker, then activate this publication.
begin;
do $model_feedback_catalog$
declare contracts jsonb:=$model_feedback_contracts$[
  {
    "name": "read_model_feedback",
    "description": "Read the exact model presentation attached to this user turn and its latest scoped feedback. Includes source freshness and user/Bob authority. not_shown means this turn has no displayed model binding; selection or alignment prose does not prove a preview was seen. Historical feedback is context, not acceptance of changed sources. No geometry reread. before_feedback_id=null reads the latest page; reuse next_feedback_id to read earlier responses.",
    "parameters": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "before_feedback_id": {
          "type": [
            "string",
            "null"
          ]
        }
      },
      "required": [
        "before_feedback_id"
      ]
    }
  },
  {
    "name": "record_model_feedback",
    "description": "Record the meaning of the ordinary response to the shown model, without a second confirmation. Consider the whole response: agreement with a correction is change_requested; silence or ambiguity is not acceptance. Scope concerns intended form/function, never safety or technical verification. The server binds actor, shown revision and current turn. user records this reply; delegated preserves an explicit mandate without accepting the model. bob acceptance reuses mandate_id from a current delegated response. No private chat text is shared. A stale presentation requires reconciliation, not rebinding the old reply to a new version.",
    "parameters": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "outcome": {
          "type": "string",
          "enum": [
            "accepted",
            "change_requested",
            "unclear",
            "delegated"
          ]
        },
        "authority": {
          "type": "string",
          "enum": [
            "user",
            "bob"
          ]
        },
        "mandate_id": {
          "type": [
            "string",
            "null"
          ]
        },
        "scope": {
          "type": "string",
          "enum": [
            "whole_model",
            "components"
          ]
        },
        "component_ids": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "maxItems": 48,
          "description": "Exact active concept component IDs for limited scope. Empty for whole_model; the server expands that scope."
        },
        "has_corrections": {
          "type": "boolean"
        },
        "has_uncertainty": {
          "type": "boolean"
        }
      },
      "required": [
        "outcome",
        "authority",
        "mandate_id",
        "scope",
        "component_ids",
        "has_corrections",
        "has_uncertainty"
      ]
    }
  }
]$model_feedback_contracts$::jsonb;
 policies jsonb:=$model_feedback_policies$[
  {
    "name": "read_model_feedback",
    "description": "Read the shown model and its scoped feedback.",
    "how_to": "The current user turn binds the presentation. Read its exact source, freshness and response/mandate history without loading geometry.",
    "schema_version": 1,
    "always_load": false,
    "preload_phases": [],
    "active": true
  },
  {
    "name": "record_model_feedback",
    "description": "Save ordinary feedback on the shown model.",
    "how_to": "Interpret the whole response in the normal conversation. Preserve corrections, ambiguity, scope and user versus Bob mandate. Shared metadata excludes private chat; technical checks remain separate.",
    "schema_version": 1,
    "always_load": false,
    "preload_phases": [],
    "active": true
  }
]$model_feedback_policies$::jsonb;
 workflow jsonb:=$model_feedback_workflow${
  "name": "workflow_solution_concept",
  "tools": [
    "read_model_feedback",
    "record_model_feedback"
  ],
  "method": " Read the shown-model binding and durable response with read_model_feedback. Record ordinary feedback through record_model_feedback; use its component identities for limited corrections and its current delegation for Bob decisions. Then correct the same Solution with existing edits. Selection or alignment prose alone is not visual feedback, and user feedback does not waive technical checks."
}$model_feedback_workflow$::jsonb;
 patch jsonb; policy jsonb; prior shared.ai_prompt_versions; template shared.ai_prompt_versions;
 prompt_uuid uuid; version_uuid uuid; next_version integer; definition jsonb; activation jsonb:='{}';
begin
 if to_regprocedure('bob.record_model_feedback(text,uuid,uuid,bigint,jsonb)') is null then raise exception 'model_feedback_core_required';end if;
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 select v.* into template from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='tools.save_project_description';
 if not found then raise exception 'bound_edit_template_missing'; end if;
 for patch in select value from jsonb_array_elements(contracts) loop
  select value into policy from jsonb_array_elements(policies) where value->>'name'=patch->>'name';
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='tools.'||(patch->>'name');
  if not found then
   insert into shared.ai_prompts(app,prompt_key,label,description,content,flow,definition_kind)
    values('bob','tools.'||(patch->>'name'),policy->>'description',policy->>'description','','','tool_contract') returning id into prompt_uuid;
   prior:=template;
  else prompt_uuid:=prior.prompt_id;
  end if;
  definition:=prior.definition||patch||jsonb_build_object('handler',patch->>'name','required_parameters',patch#>'{parameters,required}','optional_parameters','[]'::jsonb,'additional_description',policy->>'how_to','card_description',policy->>'description');
  definition:=jsonb_set(definition,'{envelope,schema_version}','1'::jsonb);
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prompt_uuid;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prompt_uuid,next_version,'tool_contract',1,jsonb_build_object('publication','model-feedback-v1','server_fields','[]'::jsonb),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object('tools.'||(patch->>'name'),version_uuid);
 end loop;
 select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='bob.tools' for update of p;
 if not found then raise exception 'bound_edit_toolbox_missing'; end if;
 definition:=prior.definition;
 for policy in select value from jsonb_array_elements(policies) loop
  insert into bob.tool_catalog(name,description,how_to,schema_version,always_load,preload_phases,active)
   values(policy->>'name',policy->>'description',policy->>'how_to',(policy->>'schema_version')::integer,(policy->>'always_load')::boolean,array(select jsonb_array_elements_text(policy->'preload_phases')),(policy->>'active')::boolean)
   on conflict(name) do nothing;
  if not exists(select 1 from jsonb_array_elements(definition->'catalog') r where r->>'name'=policy->>'name') then
   definition:=jsonb_set(definition,'{catalog}',definition->'catalog'||jsonb_build_array(policy));
  end if;
  if not definition->'contract_keys'?('tools.'||(policy->>'name')) then
   definition:=jsonb_set(definition,'{contract_keys}',definition->'contract_keys'||jsonb_build_array('tools.'||(policy->>'name')));
  end if;
  definition:=jsonb_set(definition,'{shelves}',(select jsonb_agg(case when shelf->>'label'='Project records and memory' and not shelf->'tools'?(policy->>'name') then jsonb_set(shelf,'{tools}',shelf->'tools'||jsonb_build_array(policy->>'name')) else shelf end) from jsonb_array_elements(definition->'shelves') shelf));
 end loop;
 select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
 insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
  values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','model-feedback-v1'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
 activation:=activation||jsonb_build_object('bob.tools',version_uuid);
 select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='bob.workflows' for update of p;
 if not found or not exists(select 1 from jsonb_array_elements(prior.definition->'workflows') w where w->>'name'=workflow->>'name') then raise exception 'model_feedback_workflow_missing';end if;
 definition:=jsonb_set(prior.definition,'{workflows}',(select jsonb_agg(case when w->>'name'=workflow->>'name' then
  jsonb_set(jsonb_set(w,'{tools}',(w->'tools')||(workflow->'tools')),'{method}',to_jsonb((w->>'method')||(workflow->>'method'))) else w end) from jsonb_array_elements(prior.definition->'workflows') w));
 select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
 insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
  values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','model-feedback-v1'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
 activation:=activation||jsonb_build_object('bob.workflows',version_uuid);
 perform shared.activate_ai_catalog('bob',activation);
end $model_feedback_catalog$;
commit;
